import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: LootRegistry","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: LootRegistry"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/loot/classes/LootRegistry"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/loot/classes/LootRegistry"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/loot/src"}},"headers":[],"relativePath":"api/@jsprismarine/loot/classes/LootRegistry.md","filePath":"api/@jsprismarine/loot/classes/LootRegistry.md","lastUpdated":1793831505000}`),a={name:`api/@jsprismarine/loot/classes/LootRegistry.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/loot</a> / LootRegistry</p><h1 id="class-lootregistry" tabindex="-1">Class: LootRegistry <a class="header-anchor" href="#class-lootregistry" aria-label="Permalink to “Class: LootRegistry”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L148" target="_blank" rel="noreferrer">loot/src/registry.ts:148</a></p><p>The loot tables a pack stack registered.</p><p>A table compiles on first use and stays compiled, so a chest opened a thousand times parses once. References between tables resolve through the same stack, and a reference that leads back to its own table reports a cycle instead of recursing.</p><p>Three of the content seams are answered from the stack rather than asked of the host, because the stack already carries what they need: <a href="./../#recipes">LootContentOptions.recipes</a> is the stack&#39;s own Java recipes, which is what <code>furnace_smelt</code> smelts through; <a href="./../#itemtag">LootContentOptions.itemTag</a> expands an item tag a smelting ingredient names; and <a href="./../#parse">LootContentOptions.parse</a> resolves the references a <code>set_contents</code> entry list may name. A host that passes any of them keeps its own.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new LootRegistry</strong>(<code>definitions</code>, <code>options?</code>): <code>LootRegistry</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L163" target="_blank" rel="noreferrer">loot/src/registry.ts:163</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="definitions" tabindex="-1">definitions <a class="header-anchor" href="#definitions" aria-label="Permalink to “definitions”">​</a></h5><p><a href="./../#lootpackdefinitions"><code>LootPackDefinitions</code></a></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#lootregistryoptions"><code>LootRegistryOptions</code></a> = <code>{}</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>LootRegistry</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="diagnostics" tabindex="-1">diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “diagnostics”">​</a></h3><blockquote><p><code>readonly</code> <strong>diagnostics</strong>: <a href="./../../predicates/classes/DiagnosticCollector.html"><code>DiagnosticCollector</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L150" target="_blank" rel="noreferrer">loot/src/registry.ts:150</a></p><p>Everything parsing and rolling reported, in the order it was reported.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="cycles" tabindex="-1">cycles <a class="header-anchor" href="#cycles" aria-label="Permalink to “cycles”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>cycles</strong>(): readonly <a href="./../#loottablecycle"><code>LootTableCycle</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L291" target="_blank" rel="noreferrer">loot/src/registry.ts:291</a></p><p>Every cycle in the reference graph, found over the raw JSON without compiling anything. Computed once and kept.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p>readonly <a href="./../#loottablecycle"><code>LootTableCycle</code></a>[]</p><hr><h3 id="dialect" tabindex="-1">dialect <a class="header-anchor" href="#dialect" aria-label="Permalink to “dialect”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>dialect</strong>(): <code>&quot;java&quot;</code> | <code>&quot;bedrock&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L184" target="_blank" rel="noreferrer">loot/src/registry.ts:184</a></p><p>Which edition&#39;s spelling the registered tables are written in, as the source stated it.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><code>&quot;java&quot;</code> | <code>&quot;bedrock&quot;</code></p><hr><h3 id="findings" tabindex="-1">findings <a class="header-anchor" href="#findings" aria-label="Permalink to “findings”">​</a></h3><h4 id="get-signature-2" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-2" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>findings</strong>(): readonly <a href="./../#lootfinding"><code>LootFinding</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L211" target="_blank" rel="noreferrer">loot/src/registry.ts:211</a></p><p>Everything reported so far, each attributed to the table it came from.</p><p>This is <a href="#diagnostics">diagnostics</a> for a host that writes its own report, such as one naming the pack and the file a finding sits in. Call <a href="#validate">validate</a> first for the whole picture; on its own this holds only what the tables compiled so far reported.</p><h5 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h5><p>readonly <a href="./../#lootfinding"><code>LootFinding</code></a>[]</p><hr><h3 id="ids" tabindex="-1">ids <a class="header-anchor" href="#ids" aria-label="Permalink to “ids”">​</a></h3><h4 id="get-signature-3" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-3" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>ids</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L179" target="_blank" rel="noreferrer">loot/src/registry.ts:179</a></p><p>The namespaced ids the pack stack registered, in load order.</p><h5 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h5><p>readonly <code>string</code>[]</p><hr><h3 id="worldseed" tabindex="-1">worldSeed <a class="header-anchor" href="#worldseed" aria-label="Permalink to “worldSeed”">​</a></h3><h4 id="get-signature-4" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-4" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>worldSeed</strong>(): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L189" target="_blank" rel="noreferrer">loot/src/registry.ts:189</a></p><p>The world seed every sequenced stream is keyed from.</p><h5 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h5><p><code>bigint</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="restorerandomstate" tabindex="-1">restoreRandomState() <a class="header-anchor" href="#restorerandomstate" aria-label="Permalink to “restoreRandomState()”">​</a></h3><blockquote><p><strong>restoreRandomState</strong>(<code>state</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L199" target="_blank" rel="noreferrer">loot/src/registry.ts:199</a></p><p>Restores the registry streams from a JSON-parsed state with the same world seed.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h5><p><code>unknown</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="roll" tabindex="-1">roll() <a class="header-anchor" href="#roll" aria-label="Permalink to “roll()”">​</a></h3><blockquote><p><strong>roll</strong>(<code>id</code>, <code>request?</code>): readonly <a href="./../../predicates/#itemstack"><code>ItemStack</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L261" target="_blank" rel="noreferrer">loot/src/registry.ts:261</a></p><p>Rolls a table by id. The context key set comes from the table and the randomness from the table&#39;s own sequence, so the only thing a caller has to supply is the loot context parameters.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>string</code></p><h5 id="request" tabindex="-1">request? <a class="header-anchor" href="#request" aria-label="Permalink to “request?”">​</a></h5><p><a href="./../#lootrollrequest"><code>LootRollRequest</code></a> = <code>{}</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../../predicates/#itemstack"><code>ItemStack</code></a>[]</p><hr><h3 id="saverandomstate" tabindex="-1">saveRandomState() <a class="header-anchor" href="#saverandomstate" aria-label="Permalink to “saveRandomState()”">​</a></h3><blockquote><p><strong>saveRandomState</strong>(): <a href="./../#lootsequencesstate"><code>LootSequencesState</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L194" target="_blank" rel="noreferrer">loot/src/registry.ts:194</a></p><p>Captures the advanced named and unkeyed streams used by this registry.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#lootsequencesstate"><code>LootSequencesState</code></a></p><hr><h3 id="table" tabindex="-1">table() <a class="header-anchor" href="#table" aria-label="Permalink to “table()”">​</a></h3><blockquote><p><strong>table</strong>(<code>id</code>): <a href="./../#loottable"><code>LootTable</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L233" target="_blank" rel="noreferrer">loot/src/registry.ts:233</a></p><p>Compiles a table, or returns undefined when the stack has no such id. Parse diagnostics land in <a href="#diagnostics">diagnostics</a>.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-1" tabindex="-1">id <a class="header-anchor" href="#id-1" aria-label="Permalink to “id”">​</a></h5><p><code>string</code></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#loottable"><code>LootTable</code></a> | <code>undefined</code></p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>In strict mode, when the table reported an error.</p><hr><h3 id="validate" tabindex="-1">validate() <a class="header-anchor" href="#validate" aria-label="Permalink to “validate()”">​</a></h3><blockquote><p><strong>validate</strong>(): readonly <a href="./../../predicates/#diagnostic"><code>Diagnostic</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/b987b66858befc283b9f04886ef8835899aab39f/packages/loot/src/registry.ts#L313" target="_blank" rel="noreferrer">loot/src/registry.ts:313</a></p><p>Compiles every registered table and walks the reference graph, so a malformed pack fails at load rather than at the first chest.</p><p>Runs once: a second call answers from what the first reported.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../../predicates/#diagnostic"><code>Diagnostic</code></a>[]</p><p>Everything reported so far, cycles included. <a href="#findings">findings</a> is the same list with each entry&#39;s table named.</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>In strict mode, at the first table that reported an error.</p>`,115)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};